document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const i=document.getElementById("barbershop-form"),t=document.getElementById("barbershop-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=parseInt(document.getElementById("workstations").value),o=parseFloat(document.getElementById("renovation-cost").value),r=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("working-capital").value),d=parseFloat(document.getElementById("avg-haircut-price").value),c=parseFloat(document.getElementById("clients-per-day").value),p=parseFloat(document.getElementById("working-days").value),v=parseFloat(document.getElementById("barber-commission").value),u=parseFloat(document.getElementById("monthly-rent").value),g=parseFloat(document.getElementById("utilities").value),m=parseFloat(document.getElementById("supplies").value),b=parseFloat(document.getElementById("other-expenses").value);if(a<=0||d<=0||c<=0||p<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const w=o+r+l,h=a*c,$=4.33*(h*d*p),y=$*v/100,f=.15*$,k=$+f,I=12*k,E=u+g+m+b+y,B=k-E,F=12*B,M=F/I*100,P=w/F,x=F/w*100,D=I/a,R=h*p*4.33,C=k/R,L=c/25*100;let O="info";F<0?O="warning":M>35&&(O="success");let S="info";x<25?S="warning":x>50&&(S="success");let A="info";L<60?A="warning":L>80&&(A="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>✂️ Barbershop Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(w),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(B),`Margin: ${e(M)}`,O)}\n            ${s("⏱️ Payback Period",`${P.toFixed(1)} years`,`ROI: ${e(x)}`,P<=1.5?"success":"warning")}\n            ${s("📊 Utilization Rate",e(L),`${Math.round(R)} clients/month`,A)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Renovation & design</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment & furniture</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & working capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(w)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Core services (${Math.round(R)} clients × ${n(d)})</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (beard, products)</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Barber commissions (${e(v)})</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Rent</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Supplies & products</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(E)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Operational Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per station: <strong>${n(D)}/year</strong><br>\n                Daily clients: <strong>${h} (${c}/station)</strong><br>\n                Average ticket: <strong>${n(C)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${F>0?"success":"warning"}">\n              <h6>📊 Service Analysis</h6>\n              <div class="metric-subtitle">\n                Working days: <strong>${p}/week</strong><br>\n                Haircut price: <strong>${n(d)}</strong><br>\n                Barber commission: <strong>${e(v)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${B>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Daily profit: <strong>${n(F/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                +2 clients/day impact: <strong>+${n(2*a*d*p*4.33*12*(1-v/100))}/year</strong><br>\n                +$2 price increase: <strong>+${n(2*R*12*(1-v/100))}/year</strong><br>\n                +1 workstation: <strong>+${n(D*(1-v/100)-12*u/a)}/year</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${M<25?"<li>⚠️ Low profitability. Consider increasing prices or reducing barber commission rates.</li>":""}\n              ${L<60?"<li>📍 Low utilization. Improve marketing or consider location change.</li>":""}\n              ${P>2?"<li>⏰ Long payback period. Optimize startup costs or increase client traffic.</li>":""}\n              ${L>85?"<li>✅ High utilization! Consider price increases or expansion.</li>":""}\n              ${M>40?"<li>🎉 Excellent profitability! Consider opening additional locations.</li>":""}\n              <li>💼 Implement online booking system for client convenience.</li>\n              <li>📱 Develop strong social media presence showcasing barber work.</li>\n              <li>🎯 Add beard care services and men's grooming product sales.</li>\n              <li>🤝 Create loyalty programs for regular customers.</li>\n              <li>📈 Optimize working hours based on peak visitation times.</li>\n              <li>⭐ Invest in barber training for new techniques and trends.</li>\n              <li>🎪 Consider themed promotions and seasonal offers.</li>\n              <li>🚗 Ensure convenient parking for customers.</li>\n              <li>💎 Create premium service area with additional offerings.</li>\n              <li>🌐 Implement customer feedback systems for continuous improvement.</li>\n              <li>💳 Offer membership packages and subscription services.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.barbershopBusinessData={"Number of Workstations":a,"Total Investment ($)":w,"Monthly Revenue ($)":k,"Monthly Expenses ($)":E,"Monthly Profit ($)":B,"Annual Profit ($)":F,"Profit Margin (%)":M,"Annual ROI (%)":x,"Payback Period (years)":P,"Clients per Month":R,"Utilization Rate (%)":L,"Haircut Price ($)":d,"Revenue per Station ($)":D}}),window.downloadCSV=function(){if(!window.barbershopBusinessData)return;const n=Object.entries(window.barbershopBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="barbershop-business-plan.csv",s.click()}});